import React,{useState} from 'react';
export default function Learning({state='ready'}){const [answer,setAnswer]=useState('');const [checked,setChecked]=useState(false);if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
return <div className="shell"><span className="eyebrow">Learning / Systems thinking</span><h1>Try the idea before you memorize it.</h1><p>A small interaction designed around understanding, not passive content.</p><section className="panel"><h2>When a user submits a risky action, what should happen first?</h2><div className="steps"><button id="answer" className={answer==='confirm'?'btn':'btn ghost'} onClick={()=>{setAnswer('confirm');setChecked(false);}}>Check authority and confirm</button><button className={answer==='execute'?'btn':'btn ghost'} onClick={()=>{setAnswer('execute');setChecked(false);}}>Execute and explain afterward</button></div><button id="check" className="btn spacer" disabled={!answer} onClick={()=>setChecked(true)}>Check understanding</button><p id="result" role="status">{checked?(answer==='confirm'?'Correct. Confirm the exact action and recheck the current permissions.':'Try again. An explanation cannot undo every consequence.'):'Choose an answer, then check your reasoning.'}</p></section></div>;}
